/* ========================================================================= */
/* TYPES                                                                     */
/* ========================================================================= */

type LanguageCode =
  | "en"
  | "hi"
  | "mr"
  | "kok"
  | "sa"
  | "sd"
  | "as"
  | "bn"
  | "brx"
  | "doi"
  | "gu"
  | "kn"
  | "ks"
  | "mai"
  | "ml"
  | "mni"
  | "ne"
  | "or"
  | "pa"
  | "sat"
  | "ta"
  | "te"
  | "ur";

type QuestionOption = {
  value: string;
  label: string;
};

type QuestionCondition = {
  questionId: string;
  values: string[];
  mode?: "equals" | "includes";
};

type Question = {
  id: string;
  section: string;
  text: string;
  options?: QuestionOption[];
  allowFreeText?: boolean;
  allowMultiple?: boolean;
  required?: boolean;
  complaint?: string;
  conditions?: QuestionCondition[];
  field?:
    | "chiefComplaint"
    | "prakriti.skin"
    | "prakriti.appetite";
};

