/* ========================================================================= */
/* TRANSLATION HELPERS                                                       */
/* ========================================================================= */

function normalizeLanguage(
  language: string
): MediKioskLanguage {
  if (
    ALL_LANGUAGES.includes(
      language as MediKioskLanguage
    )
  ) {
    return language as MediKioskLanguage;
  }

  return "en";
}

function translateHistoryUI(
  language: string,
  key: string
): string {
  const lang =
    normalizeLanguage(language);

  return (
    historyUiTranslations[lang]?.[key] ??
    historyUiTranslations.en[key] ??
    translateUI(lang, key)
  );
}

function translateQuestionText(
  question: Question,
  language: string
): string {
  const lang =
    normalizeLanguage(language);

  const translation =
    questionTextTranslations[
      question.id
    ];

  const legacyTranslation =
    questionTranslations[
      question.id
    ];

  return (
    translation?.[lang] ??
    translation?.en ??
    legacyTranslation?.[lang] ??
    legacyTranslation?.en ??
    question.text
  );
}



