function translateAnyOption(
  option: QuestionOption,
  language: string
): string {
  const normal =
    optionTranslations[
      option.value
    ];

  const special =
    specialOptionTranslations[
      option.value
    ];

  const lang =
    normalizeLanguage(language);

  return (
    normal?.[lang] ??
    special?.[lang] ??
    normal?.en ??
    special?.en ??
    option.label
  );
}

