/* ========================================================================= */
/* INITIAL CHIEF COMPLAINT QUESTION                                           */
/* ========================================================================= */

function createChiefComplaintQuestion(): Question {
  return {
    id: "CHIEF_COMPLAINT",
    section: "Chief Complaint",
    text:
      "What brings you here today? Please tell me in your own words.",
    options: complaintOptions,

    /*
     * Chief Complaint is multi-select so patients can
     * report more than one reason for the visit.
     */
    allowMultiple: true,

    /*
     * ONLY THIS QUESTION allows manual typing.
     *
     * Patient can either:
     *
     * 1. Select one or more predefined complaints
     * 2. Select Other
     * 3. Use voice
     * 4. Type own words
     */
    allowFreeText: true,

    required: true,
  };
}

/* ========================================================================= */
/* OTHER FREE TEXT QUESTION                                                   */
/* ========================================================================= */

function createOtherFreeTextQuestion(): Question {
  return {
    id: "OTHER_FREE_TEXT",
    section: "Chief Complaint",
    text:
      "Please describe your problem in your own words.",

    /*
     * This is the ONLY other question that allows typing.
     */
    allowFreeText: true,

    required: true,
  };
}

/* ========================================================================= */
/* BUILD INITIAL FLOW                                                        */
/* ========================================================================= */

function resolveComplaintKeys(
  chiefComplaint: string,
  selectedComplaints: SelectedComplaint[]
): string[] {
  const selectedKeys =
    selectedComplaints
      .map((item) =>
        normalizeComplaintId(item.id)
      )
      .filter(Boolean);

  if (selectedKeys.length) {
    return Array.from(
      new Set(selectedKeys)
    );
  }

  if (chiefComplaint.trim()) {
    return detectComplaintKeys(
      chiefComplaint
    );
  }

  return [];
}

function buildInitialFlow(
  chiefComplaint: string,
  selectedComplaints: SelectedComplaint[],
  historyAnswers: HistoryAnswer[]
): Question[] {
  const complaintKeys =
    resolveComplaintKeys(
      chiefComplaint,
      selectedComplaints
    );

  if (!complaintKeys.length) {
    return [
      createChiefComplaintQuestion(),
    ];
  }

  return buildComplaintFlow(
    complaintKeys,
    historyAnswers
  );
}

/* ========================================================================= */
/* BUILD ADAPTIVE COMPLAINT FLOW                                              */
/* ========================================================================= */

function buildComplaintFlow(
  complaintKeys: string[],
  historyAnswers: HistoryAnswer[]
): Question[] {
  const uniqueKeys =
    Array.from(
      new Set(
        complaintKeys
          .map(normalizeComplaintId)
          .filter(Boolean)
      )
    );

  /*
   * Each complaint is walked in order.
   *
   * Only the questions already answered plus the NEXT
   * relevant question are placed into the active flow.
   *
   * This means the kiosk never dumps an entire questionnaire
   * on the patient at once.
   */
  const complaintQuestions =
    uniqueKeys.flatMap((key) =>
      buildSequentialQuestions(
        complaintPathways[key] || [],
        historyAnswers
      )
    );

  const relevantPrakriti =
    getRelevantPrakritiQuestions(
      uniqueKeys
    );

  const prakritiQuestionsInFlow =
    buildSequentialQuestions(
      relevantPrakriti,
      historyAnswers
    );

  const commonQuestions =
    getCommonAyurvedaQuestions(
      uniqueKeys
    );

  const commonQuestionsInFlow =
    buildSequentialQuestions(
      commonQuestions,
      historyAnswers
    );

  return uniqueQuestions(
    [
      ...complaintQuestions,
      ...prakritiQuestionsInFlow,
      ...commonQuestionsInFlow,
    ].filter((question) =>
      isQuestionRelevant(
        question,
        historyAnswers
      )
    )
  );
}

/* ========================================================================= */
/* SEQUENTIAL ADAPTIVE QUESTION BUILDER                                      */
/* ========================================================================= */

function buildSequentialQuestions(
  questions: Question[],
  historyAnswers: HistoryAnswer[]
): Question[] {
  const result: Question[] = [];

  for (const question of questions) {
    if (
      !isQuestionRelevant(
        question,
        historyAnswers
      )
    ) {
      continue;
    }

    result.push(question);

    /*
     * Stop after the first unanswered relevant question.
     * Previously answered questions stay in the array so
     * the Back button can still work.
     */
    if (
      !hasAnsweredQuestion(
        question.id,
        historyAnswers
      )
    ) {
      break;
    }
  }

  return result;
}

/* ========================================================================= */
/* RELEVANT PRAKRITI QUESTIONS                                               */
/* ========================================================================= */

function getRelevantPrakritiQuestions(
  complaintKeys: string[]
): Question[] {
  const keys = new Set(
    complaintKeys.map(
      normalizeComplaintId
    )
  );

  const digestive =
    keys.has("stomach") ||
    keys.has("constipation") ||
    keys.has("diarrhea");

  const needsAppetiteContext =
    digestive ||
    keys.has("weakness") ||
    keys.has("fever-cough");

  return prakritiQuestions.filter(
    (question) => {
      if (
        question.id ===
        "PRAKRITI_SKIN"
      ) {
        return keys.has("skin");
      }

      if (
        question.id ===
        "PRAKRITI_APPETITE"
      ) {
        return needsAppetiteContext;
      }

      return false;
    }
  );
}

/* ========================================================================= */
/* COMMON AYURVEDA QUESTION FILTER                                           */
/* ========================================================================= */

function getCommonAyurvedaQuestions(
  complaintKeys: string[]
): Question[] {
  const keys = new Set(
    complaintKeys.map(
      normalizeComplaintId
    )
  );

  const digestive =
    keys.has("stomach") ||
    keys.has("constipation") ||
    keys.has("diarrhea");

  const bowelRelated =
    digestive;

  return commonAyurvedaQuestions.filter(
    (question) => {
      if (
        question.id ===
        "AGNI_APPETITE_PATTERN"
      ) {
        return (
          digestive ||
          keys.has("weakness")
        );
      }

      if (
        question.id ===
        "KOSHTHA_PATTERN"
      ) {
        return bowelRelated;
      }

      if (
        question.id ===
        "STOOL_CONSISTENCY"
      ) {
        return (
          keys.has("constipation") ||
          keys.has("diarrhea")
        );
      }

      /*
       * Nidana and Samprapti remain useful across
       * complaint pathways because they describe
       * triggers, relieving factors and progression.
       */
      return true;
    }
  );
}

/* ========================================================================= */
/* ADAPTIVE CONDITION ENGINE                                                 */
/* ========================================================================= */

type StoredHistoryAnswer =
  HistoryAnswer & {
    structuredAnswer?: string;
  };

function getStoredStructuredValues(
  answer: HistoryAnswer
): string[] {
  const stored =
    answer as StoredHistoryAnswer;

  if (
    stored.structuredAnswer?.trim()
  ) {
    return stored.structuredAnswer
      .split("|")
      .map((value) =>
        value.trim()
      )
      .filter(Boolean);
  }

  return [];
}

function findQuestionDefinition(
  questionId: string
): Question | undefined {
  if (
    questionId ===
    "CHIEF_COMPLAINT"
  ) {
    return createChiefComplaintQuestion();
  }

  for (const questions of Object.values(
    complaintPathways
  )) {
    const found =
      questions.find(
        (question) =>
          question.id ===
          questionId
      );

    if (found) {
      return found;
    }
  }

  const prakritiFound =
    prakritiQuestions.find(
      (question) =>
        question.id ===
        questionId
    );

  if (prakritiFound) {
    return prakritiFound;
  }

  return commonAyurvedaQuestions.find(
    (question) =>
      question.id ===
      questionId
  );
}

function normalizeConditionValue(
  value: string
): string {
  return value
    .toLowerCase()
    .trim();
}

function answerMatchesCondition(
  answer: HistoryAnswer,
  condition: QuestionCondition
): boolean {
  const structuredValues =
    getStoredStructuredValues(
      answer
    );

  if (structuredValues.length) {
    const normalized =
      structuredValues.map(
        normalizeConditionValue
      );

    if (
      condition.mode ===
      "includes"
    ) {
      return condition.values.some(
        (value) =>
          normalized.includes(
            normalizeConditionValue(
              value
            )
          )
      );
    }

    return condition.values.some(
      (value) =>
        normalized.includes(
          normalizeConditionValue(
            value
          )
        )
    );
  }

  /*
   * Backward-compatible fallback for answers saved
   * before structuredAnswer was introduced.
   */
  const storedText =
    normalizeConditionValue(
      answer.answer || ""
    );

  const definition =
    findQuestionDefinition(
      answer.questionId
    );

  if (!definition) {
    return condition.values.some(
      (value) =>
        storedText ===
        normalizeConditionValue(
          value
        )
    );
  }

  return condition.values.some(
    (value) => {
      const expected =
        normalizeConditionValue(
          value
        );

      if (
        storedText === expected
      ) {
        return true;
      }

      const option =
        definition.options?.find(
          (item) =>
            normalizeConditionValue(
              item.value
            ) === expected
        );

      if (!option) {
        return false;
      }

      return (
        storedText ===
          normalizeConditionValue(
            option.label
          ) ||
        SUPPORTED_LANGUAGE_CODES.some(
          (language) =>
            storedText ===
            normalizeConditionValue(
              translateAnyOption(
                option,
                language
              )
            )
        )
      );
    }
  );
}

const SUPPORTED_LANGUAGE_CODES:
  LanguageCode[] = [
    "en",
    "hi",
    "mr",
    "kok",
    "sa",
    "sd",
    "as",
    "bn",
    "brx",
    "doi",
    "gu",
    "kn",
    "ks",
    "mai",
    "ml",
    "mni",
    "ne",
    "or",
    "pa",
    "sat",
    "ta",
    "te",
    "ur",
  ];

function hasAnsweredQuestion(
  questionId: string,
  historyAnswers: HistoryAnswer[]
): boolean {
  return historyAnswers.some(
    (answer) =>
      answer.questionId ===
        questionId &&
      Boolean(
        answer.answer?.trim()
      )
  );
}

function isQuestionRelevant(
  question: Question,
  historyAnswers: HistoryAnswer[]
): boolean {
  if (
    !question.conditions?.length
  ) {
    return true;
  }

  return question.conditions.every(
    (condition) => {
      const answer =
        [...historyAnswers]
          .reverse()
          .find(
            (item) =>
              item.questionId ===
              condition.questionId &&
              Boolean(
                item.answer?.trim()
              )
          );

      if (!answer) {
        return false;
      }

      return answerMatchesCondition(
        answer,
        condition
      );
    }
  );
}

/* ========================================================================= */
/* NEXT QUESTION                                                             */
/* ========================================================================= */

function findNextQuestionIndex(
  questions: Question[],
  startIndex: number,
  historyAnswers: HistoryAnswer[],
  currentQuestionId: string
): number {
  const answered =
    new Set(
      historyAnswers
        .filter(
          (answer) =>
            answer.answer?.trim()
        )
        .map(
          (answer) =>
            answer.questionId
        )
    );

  answered.add(
    currentQuestionId
  );

  for (
    let index = startIndex;
    index < questions.length;
    index += 1
  ) {
    if (
      !answered.has(
        questions[index].id
      )
    ) {
      return index;
    }
  }

  return -1;
}

/* ========================================================================= */
/* UNIQUE QUESTIONS                                                          */
/* ========================================================================= */

function uniqueQuestions(
  questions: Question[]
): Question[] {
  const seen =
    new Set<string>();

  return questions.filter(
    (question) => {
      if (
        seen.has(
          question.id
        )
      ) {
        return false;
      }

      seen.add(
        question.id
      );

      return true;
    }
  );
}

/* ========================================================================= */
/* COMPLAINT DETECTION                                                       */
/* ========================================================================= */

function detectComplaintKeys(
  text: string
): string[] {
  const normalized =
    text
      .toLowerCase()
      .trim();

  const detected: string[] = [];

  const add = (
    key: string
  ) => {
    if (
      !detected.includes(key)
    ) {
      detected.push(key);
    }
  };

  if (
    normalized.includes("headache") ||
    normalized.includes("head pain") ||
    normalized.includes("migraine") ||
    normalized.includes("shira shula") ||
    normalized.includes("सिरदर्द") ||
    normalized.includes("सिर दर्द") ||
    normalized.includes("डोकेदुखी") ||
    normalized.includes("डोके दुखणे")
  ) {
    add("headache");
  }

  if (
    normalized.includes("joint") ||
    normalized.includes("knee") ||
    normalized.includes("arthritis") ||
    normalized.includes("sandhi") ||
    normalized.includes("जोड़") ||
    normalized.includes("सांधा") ||
    normalized.includes("संधी")
  ) {
    add("joint-pain");
  }

  if (
    normalized.includes("stomach") ||
    normalized.includes("acidity") ||
    normalized.includes("gas") ||
    normalized.includes("indigestion") ||
    normalized.includes("amlapitta") ||
    normalized.includes("पेट") ||
    normalized.includes("आम्लपित्त") ||
    normalized.includes("पोट")
  ) {
    add("stomach");
  }

  if (
    normalized.includes("skin") ||
    normalized.includes("rash") ||
    normalized.includes("itch") ||
    normalized.includes("itching") ||
    normalized.includes("tvak") ||
    normalized.includes("त्वचा") ||
    normalized.includes("खाज")
  ) {
    add("skin");
  }

  if (
    normalized.includes("sleep") ||
    normalized.includes("insomnia") ||
    normalized.includes("anidra") ||
    normalized.includes("नींद") ||
    normalized.includes("झोप")
  ) {
    add("sleep");
  }

  if (
    normalized.includes("weak") ||
    normalized.includes("weakness") ||
    normalized.includes("fatigue") ||
    normalized.includes("tired") ||
    normalized.includes("daurbalya") ||
    normalized.includes("कमजोरी") ||
    normalized.includes("अशक्तपणा")
  ) {
    add("weakness");
  }

  if (
    normalized.includes("fever") ||
    normalized.includes("cough") ||
    normalized.includes("jwara") ||
    normalized.includes("kasa") ||
    normalized.includes("बुखार") ||
    normalized.includes("खांसी") ||
    normalized.includes("ताप") ||
    normalized.includes("खोकला")
  ) {
    add("fever-cough");
  }

  if (
    normalized.includes("constipation") ||
    normalized.includes("hard stool") ||
    normalized.includes("vibandha") ||
    normalized.includes("कब्ज") ||
    normalized.includes("बद्धकोष्ठता")
  ) {
    add("constipation");
  }

  if (
    normalized.includes("diarrhea") ||
    normalized.includes("diarrhoea") ||
    normalized.includes("loose stool") ||
    normalized.includes("loose motion") ||
    normalized.includes("atisara") ||
    normalized.includes("दस्त") ||
    normalized.includes("जुलाब")
  ) {
    add("diarrhea");
  }

  if (
    normalized.includes("back pain") ||
    normalized.includes("lower back") ||
    normalized.includes("low back") ||
    normalized.includes("kati shula") ||
    normalized.includes("कमर") ||
    normalized.includes("कंबर")
  ) {
    add("low-back");
  }

  if (
    normalized.includes("eye") ||
    normalized.includes("eyes") ||
    normalized.includes("blurred vision") ||
    normalized.includes("netra") ||
    normalized.includes("आंख") ||
    normalized.includes("आँख") ||
    normalized.includes("डोळे")
  ) {
    add("eye");
  }

  return detected;
}

/* ========================================================================= */
/* NORMALIZE COMPLAINT ID                                                    */
/* ========================================================================= */

function normalizeComplaintId(
  id: string
): string {
  const value =
    id
      .toLowerCase()
      .trim();

  if (
    value === "headache" ||
    value === "shira-shula"
  ) {
    return "headache";
  }

  if (
    value === "joint-pain" ||
    value === "joint" ||
    value === "sandhi-shula"
  ) {
    return "joint-pain";
  }

  if (
    value === "stomach" ||
    value === "acidity" ||
    value === "amla" ||
    value === "amlapitta"
  ) {
    return "stomach";
  }

  if (
    value === "skin" ||
    value === "tvak-roga"
  ) {
    return "skin";
  }

  if (
    value === "sleep" ||
    value === "anidra"
  ) {
    return "sleep";
  }

  if (
    value === "weakness" ||
    value === "daurbalya"
  ) {
    return "weakness";
  }

  if (
    value === "fever-cough" ||
    value === "jwara" ||
    value === "kasa"
  ) {
    return "fever-cough";
  }

  if (
    value === "constipation" ||
    value === "vibandha"
  ) {
    return "constipation";
  }

  if (
    value === "diarrhea" ||
    value === "diarrhoea" ||
    value === "atisara"
  ) {
    return "diarrhea";
  }

  if (
    value === "low-back" ||
    value === "back" ||
    value === "kati-shula"
  ) {
    return "low-back";
  }

  if (
    value === "eye" ||
    value === "netra"
  ) {
    return "eye";
  }

  return "";
}

/* ========================================================================= */
/* COMPLAINT KEY FALLBACK                                                    */
/* ========================================================================= */

function getComplaintKey(
  complaint: string
): string {
  const detected =
    detectComplaintKeys(
      complaint
    );

  return (
    detected[0] ||
    "other"
  );
}

/* ========================================================================= */
/* OTHER COMPLAINT MAPPING                                                   */
/* ========================================================================= */

function mapOtherCategoryToComplaintKey(
  category: string
): string {
  const map: Record<
    string,
    string
  > = {
    digestive: "stomach",
    respiratory: "fever-cough",
    skin: "skin",
    general: "weakness",
  };

  return (
    map[category] || ""
  );
}

function mapOtherSpecificToComplaintKey(
  value: string
): string {
  const map: Record<
    string,
    string
  > = {
    "chest-pain": "",
    "neck-pain": "joint-pain",
    "shoulder-pain": "joint-pain",
    "back-pain": "low-back",
    "leg-pain": "low-back",
    "nausea-vomiting": "stomach",
    "loss-of-appetite": "stomach",
    indigestion: "stomach",
    "gas-bloating": "stomach",
    "burning-urination": "",
    "frequent-urination": "",
    "difficulty-urinating": "",
    "other-urinary": "",
    "menstrual-problem": "",
    "irregular-periods": "",
    "menstrual-pain": "",
    "excessive-bleeding": "",
    "other-womens-health": "",
    itching: "skin",
    rash: "skin",
    dryness: "skin",
    "hair-problem": "skin",
    "other-skin": "skin",
    fatigue: "weakness",
    weakness: "weakness",
    dizziness: "weakness",
    "weight-change": "weakness",
    "other-general": "",
    breathlessness: "fever-cough",
    cold: "fever-cough",
    cough: "fever-cough",
    "throat-discomfort": "fever-cough",
    "other-respiratory": "fever-cough",
  };

  return (
    map[value] || ""
  );
}

/* ========================================================================= */
/* DISPLAY NAME                                                              */
/* ========================================================================= */

function getComplaintDisplayName(
  complaint: string,
  language: string
): string {
  return translateComplaintOption(
    complaint,
    language
  );
}

/* ========================================================================= */
/* SECTION TRANSLATION                                                       */
/* ========================================================================= */

function translateSection(
  section: string,
  language: string
): string {
  const normalized =
    section.toLowerCase();

  if (
    normalized ===
    "chief complaint"
  ) {
    return translateHistoryUI(
      language,
      "chiefComplaint"
    );
  }

  if (
    normalized ===
    "prakriti"
  ) {
    return translateHistoryUI(
      language,
      "prakriti"
    );
  }

  if (
    normalized ===
    "vikriti"
  ) {
    return translateHistoryUI(
      language,
      "vikriti"
    );
  }

  if (
    normalized ===
    "nidana"
  ) {
    return translateHistoryUI(
      language,
      "nidana"
    );
  }

  if (
    normalized ===
    "samprapti"
  ) {
    return translateHistoryUI(
      language,
      "samprapti"
    );
  }

  if (
    normalized ===
    "agni"
  ) {
    return translateHistoryUI(
      language,
      "agni"
    );
  }

  if (
    normalized ===
    "koshtha"
  ) {
    return translateHistoryUI(
      language,
      "koshtha"
    );
  }

  return section;
}

/* ========================================================================= */
/* STRUCTURED VALUE UPDATE                                                   */
/* ========================================================================= */

function updateStructuredValue(
  question: Question,
  answer: string
) {
  const store =
    usePatientStore.getState();

  if (
    question.field ===
    "chiefComplaint"
  ) {
    store.setChiefComplaint(
      answer
    );

    return;
  }

  if (
    question.field ===
    "prakriti.skin"
  ) {
    store.setPrakriti({
      skin:
        answer,
    });

    return;
  }

  if (
    question.field ===
    "prakriti.appetite"
  ) {
    store.setPrakriti({
      appetite:
        answer,
    });
  }
}

/* ========================================================================= */
/* MODE DESCRIPTION                                                          */
/* ========================================================================= */

function getModeDescription(
  mode: InteractionMode,
  language: string
): string {
  const lang =
    normalizeLanguage(language);

  const descriptions: Record<
    MediKioskLanguage,
    Partial<
      Record<
        InteractionMode,
        string
      >
    >
  > = {
    en: {
      "voice-to-voice":
        "Voice → Voice · Listen to the question and answer naturally by voice",

      "voice-to-text":
        "Voice → Text · Read the question, select an option or answer by voice",

      "text-to-voice":
        "Text → Voice · Hear the question and select an option by touch",

      "text-to-text":
        "Text → Text · Read the question and select an option by touch",
    },

    hi: {
      "voice-to-voice":
        "आवाज़ → आवाज़ · प्रश्न सुनें और स्वाभाविक रूप से आवाज़ में उत्तर दें",

      "voice-to-text":
        "आवाज़ → टेक्स्ट · प्रश्न पढ़ें, विकल्प चुनें या आवाज़ से उत्तर दें",

      "text-to-voice":
        "टेक्स्ट → आवाज़ · प्रश्न सुनें और स्पर्श करके विकल्प चुनें",

      "text-to-text":
        "टेक्स्ट → टेक्स्ट · प्रश्न पढ़ें और स्पर्श करके विकल्प चुनें",
    },

    mr: {
      "voice-to-voice":
        "आवाज → आवाज · प्रश्न ऐका आणि नैसर्गिकपणे आवाजाने उत्तर द्या",

      "voice-to-text":
        "आवाज → मजकूर · प्रश्न वाचा, पर्याय निवडा किंवा आवाजाने उत्तर द्या",

      "text-to-voice":
        "मजकूर → आवाज · प्रश्न ऐका आणि स्पर्श करून पर्याय निवडा",

      "text-to-text":
        "मजकूर → मजकूर · प्रश्न वाचा आणि स्पर्श करून पर्याय निवडा",
    },

    kok: {},
    sa: {},
    sd: {},
    as: {},
    bn: {},
    brx: {},
    doi: {},
    gu: {},
    kn: {},
    ks: {},
    mai: {},
    ml: {},
    mni: {},
    ne: {},
    or: {},
    pa: {},
    sat: {},
    ta: {},
    te: {},
    ur: {},
  };

  return (
    descriptions[lang]?.[mode] ??
    descriptions.en[mode] ??
    ""
  );
}

/* ========================================================================= */
/* RED-FLAG / PRIORITY CHECK                                                 */
/* ========================================================================= */

function getPriorityAlert(
  question: Question,
  structuredAnswer: string
): string {
  const values =
    structuredAnswer
      .split("|")
      .map((value) =>
        value.trim()
      )
      .filter(Boolean);

  if (
    question.id ===
      "FEVER_ASSOCIATED" &&
    values.includes(
      "breathlessness"
    )
  ) {
    return "Breathing difficulty was reported. Please see healthcare staff promptly. MediKiosk will stop the normal history here.";
  }

  if (
    question.id ===
      "EYE_PROBLEM" &&
    values.includes("blurred")
  ) {
    return "A change in vision was reported. Please have this assessed by healthcare staff promptly. MediKiosk will stop the normal history here.";
  }

  if (
    question.id ===
      "OTHER_SPECIFIC" &&
    values.includes("chest-pain")
  ) {
    return "Chest pain was reported. Please seek prompt assessment from healthcare staff. MediKiosk will stop the normal history here.";
  }

  if (
    question.id ===
      "OTHER_SPECIFIC" &&
    values.includes(
      "excessive-bleeding"
    )
  ) {
    return "Significant bleeding was reported. Please seek prompt assessment from healthcare staff. MediKiosk will stop the normal history here.";
  }

  return "";
}

/* ========================================================================= */
/* MAIN COMPONENT                                                            */
/* ========================================================================= */

export default function History() {
  const navigate = useNavigate();

  const language =
    usePatientStore(
      (state) => state.language
    );

  const mode =
    usePatientStore(
      (state) => state.mode
    );

  const chiefComplaint =
    usePatientStore(
      (state) =>
        state.chiefComplaint
    );

  const setChiefComplaint =
    usePatientStore(
      (state) =>
        state.setChiefComplaint
    );

  const selectedComplaints =
    usePatientStore(
      (state) =>
        state.selectedComplaints
    );

  const historyAnswers =
    usePatientStore(
      (state) =>
        state.historyAnswers
    );

  const addHistoryAnswer =
    usePatientStore(
      (state) =>
        state.addHistoryAnswer
    );

  const [questions, setQuestions] =
    useState<Question[]>([]);

  const [questionIndex, setQuestionIndex] =
    useState(0);

  const [selectedAnswer, setSelectedAnswer] =
    useState("");

  const [freeText, setFreeText] =
    useState("");

  const [isListening, setIsListening] =
    useState(false);

  const [speechError, setSpeechError] =
    useState("");

  const [isSpeaking, setIsSpeaking] =
    useState(false);

  const [initialized, setInitialized] =
    useState(false);

  const [activeComplaintKeys, setActiveComplaintKeys] =
    useState<string[]>([]);

  const [pendingComplaintKeys, setPendingComplaintKeys] =
    useState<string[]>([]);

  const [selectedAnswers, setSelectedAnswers] =
    useState<string[]>([]);

  const [priorityAlert, setPriorityAlert] =
    useState("");

  const autoSpokenQuestion =
    useRef<string | null>(null);

  const isVoiceToVoice =
    mode === "voice-to-voice";

  const isVoiceToText =
    mode === "voice-to-text";

  const isTextToVoice =
    mode === "text-to-voice";

  const currentQuestion =
    questions[questionIndex];

  /*
   * IMPORTANT:
   *
   * Voice → Voice:
   *
   * We DO NOT require options.
   *
   * The patient can speak naturally.
   *
   * The transcript becomes the answer.
   */

  const showsOptions =
    Boolean(
      currentQuestion?.options?.length
    );

  const allowsVoice =
    isVoiceToVoice ||
    isVoiceToText;

  /*
   * Typing is deliberately restricted.
   */
  const allowsManualTyping =
    currentQuestion?.id ===
      "CHIEF_COMPLAINT" ||
    currentQuestion?.id ===
      "OTHER_FREE_TEXT";

  /* ======================================================================= */
  /* INITIALIZE                                                              */
  /* ======================================================================= */

  useEffect(() => {
    if (initialized) {
      return;
    }

    const initialComplaintKeys =
      resolveComplaintKeys(
        chiefComplaint,
        selectedComplaints
      );

    setActiveComplaintKeys(
      initialComplaintKeys
    );

    const flow =
      buildInitialFlow(
        chiefComplaint,
        selectedComplaints,
        historyAnswers
      );

    console.log(
      "===== MEDIKIOSK HISTORY ====="
    );

    console.log(
      "Chief Complaint:",
      chiefComplaint
    );

    console.log(
      "Selected Complaints:",
      selectedComplaints
    );

    console.log(
      "Existing History Answers:",
      historyAnswers
    );

    console.log(
      "Generated History Questions:",
      flow
    );

    console.log(
      "Question Count:",
      flow.length
    );

    console.log(
      "============================="
    );

    setQuestions(
      flow.length
        ? flow
        : [
            createChiefComplaintQuestion(),
          ]
    );

    setQuestionIndex(0);
    setInitialized(true);
  }, [
    initialized,
    chiefComplaint,
    selectedComplaints,
    historyAnswers,
  ]);

  /* ======================================================================= */
  /* SPEAK QUESTION                                                          */
  /* ======================================================================= */

  useEffect(() => {
    if (!currentQuestion) {
      return;
    }

    /*
     * Voice → Voice:
     *
     * Ask the question automatically.
     */

    if (
      !isVoiceToVoice &&
      !isTextToVoice
    ) {
      return;
    }

    if (
      autoSpokenQuestion.current ===
      currentQuestion.id
    ) {
      return;
    }

    autoSpokenQuestion.current =
      currentQuestion.id;

    setIsSpeaking(true);

    speakText(
      translateQuestionText(
        currentQuestion,
        language
      ),
      getSpeechLanguage(
        language
      )
    );

    const timer =
      window.setTimeout(() => {
        setIsSpeaking(false);
      }, 3000);

    return () => {
      window.clearTimeout(timer);
      stopSpeaking();
    };
  }, [
    currentQuestion,
    language,
    isVoiceToVoice,
    isTextToVoice,
  ]);

  /* ======================================================================= */
  /* CLEANUP                                                                 */
  /* ======================================================================= */

  useEffect(() => {
    return () => {
      stopListening();
      stopSpeaking();
    };
  }, []);

  /* ======================================================================= */
  /* PROGRESS                                                                */
  /* ======================================================================= */

  const progress =
    useMemo(() => {
      if (!questions.length) {
        return 0;
      }

      return Math.min(
        100,
        Math.round(
          ((questionIndex + 1) /
            questions.length) *
            100
        )
      );
    }, [
      questionIndex,
      questions.length,
    ]);

  /* ======================================================================= */
  /* OPTION SELECT                                                           */
  /* ======================================================================= */

  const handleOptionSelect = (
    option: QuestionOption
  ) => {
    /*
     * Chief Complaint is intentionally multi-select.
     *
     * A patient can arrive with more than one concern,
     * for example headache + acidity. We collect all
     * selected complaint keys and build one combined,
     * complaint-specific history.
     */
    if (
      currentQuestion?.id ===
      "CHIEF_COMPLAINT"
    ) {
      setSelectedAnswers(
        (previous) =>
          previous.includes(
            option.value
          )
            ? previous.filter(
                (value) =>
                  value !==
                  option.value
              )
            : [
                ...previous,
                option.value,
              ]
      );

      setFreeText("");
      setSelectedAnswer("");
      setSpeechError("");

      if (
        isVoiceToVoice ||
        isTextToVoice
      ) {
        speakText(
          translateAnyOption(
            option,
            language
          ),
          getSpeechLanguage(
            language
          )
        );
      }

      return;
    }

    setSelectedAnswer(
      option.value
    );

    setSelectedAnswers([]);
    setFreeText("");
    setSpeechError("");

    /*
     * Voice → Voice / Text → Voice:
     *
     * Confirm the selected option verbally.
     */
    if (
      isVoiceToVoice ||
      isTextToVoice
    ) {
      speakText(
        translateAnyOption(
          option,
          language
        ),
        getSpeechLanguage(
          language
        )
      );
    }
  };

  /* ======================================================================= */
  /* VOICE INPUT                                                             */
  /* ======================================================================= */

  const handleVoice = () => {
    if (!currentQuestion) {
      return;
    }

    if (isListening) {
      stopListening();
      setIsListening(false);
      return;
    }

    setSpeechError("");

    if (
      !isSpeechRecognitionSupported()
    ) {
      setSpeechError(
        translateHistoryUI(
          language,
          "voiceUnsupported"
        )
      );

      return;
    }

    startListening(
      getSpeechLanguage(
        language
      ),

      (result) => {
        const transcript =
          result.transcript.trim();

        if (!transcript) {
          return;
        }

        /*
         * VOICE → VOICE:
         *
         * Natural speech is accepted.
         *
         * We don't force the patient
         * to select a button.
         */

        if (
          isVoiceToVoice
        ) {
          setFreeText(
            transcript
          );

          setSelectedAnswer(
            transcript
          );

          setSelectedAnswers(
            []
          );

          setSpeechError("");

          return;
        }

        /*
         * Voice → Text:
         *
         * Voice can answer a structured
         * question as text.
         */

        setFreeText(
          transcript
        );

        setSelectedAnswer(
          transcript
        );

        setSelectedAnswers(
          []
        );

        setSpeechError("");
      },

      () => {
        setIsListening(true);
        setSpeechError("");
      },

      () => {
        setIsListening(false);
      },

      (message) => {
        setIsListening(false);
        setSpeechError(message);
      }
    );
  };

  /* ======================================================================= */
  /* ANSWER VALUE                                                            */
  /* ======================================================================= */

  const getAnswerValue =
    (): string => {
      if (
        currentQuestion?.id ===
        "CHIEF_COMPLAINT" &&
        selectedAnswers.length
      ) {
        return selectedAnswers
          .map((value) => {
            const option =
              currentQuestion.options?.find(
                (item) =>
                  item.value ===
                  value
              );

            return option
              ? translateAnyOption(
                  option,
                  language
                )
              : value;
          })
          .join(" • ");
      }

      if (
        freeText.trim()
      ) {
        return freeText.trim();
      }

      if (
        selectedAnswer.trim()
      ) {
        const option =
          currentQuestion?.options?.find(
            (item) =>
              item.value ===
              selectedAnswer
          );

        if (option) {
          return translateAnyOption(
            option,
            language
          );
        }

        return selectedAnswer;
      }

      return "";
    };

  /* ======================================================================= */
  /* STRUCTURED ANSWER VALUE                                                 */
  /* ======================================================================= */

  const getStructuredAnswerValue =
    (): string => {
      /*
       * Chief Complaint stores stable complaint IDs,
       * not translated labels.
       */
      if (
        currentQuestion?.id ===
        "CHIEF_COMPLAINT" &&
        selectedAnswers.length
      ) {
        return selectedAnswers.join(
          "|"
        );
      }

      if (
        freeText.trim()
      ) {
        return freeText.trim();
      }

      if (
        selectedAnswer.trim()
      ) {
        const option =
          currentQuestion?.options?.find(
            (item) =>
              item.value ===
              selectedAnswer
          );

        return (
          option?.value ||
          selectedAnswer
        );
      }

      return "";
    };

  /* ======================================================================= */
  /* CONTINUE                                                                */
  /* ======================================================================= */

  const handleContinue =
    () => {
      if (!currentQuestion) {
        return;
      }

      const answer =
        getAnswerValue();

      const structuredAnswer =
        getStructuredAnswerValue();

      if (!answer) {
        setSpeechError(
          isVoiceToVoice
            ? translateHistoryUI(
                language,
                "answerByVoice"
              )
            : translateHistoryUI(
                language,
                "selectOrVoice"
              )
        );

        return;
      }

      setSpeechError("");

      /*
       * Determine source.
       */

      const source =
        freeText.trim()
          ? allowsVoice
            ? "voice"
            : "text"
          : "touch";

      const historyAnswer =
        {
          questionId:
            currentQuestion.id,

          question:
            translateQuestionText(
              currentQuestion,
              language
            ),

          answer,

          /*
           * Stable value used by the adaptive engine.
           * The existing HistoryAnswer type remains
           * compatible because the extra field is optional
           * from the engine's point of view.
           */
          structuredAnswer,

          category:
            currentQuestion.section,

          subCategory:
            currentQuestion.complaint,

          complaint:
            currentQuestion.complaint,

          source,

          timestamp:
            new Date().toISOString(),
        } as HistoryAnswer & {
          structuredAnswer?: string;
        };

      /* ------------------------------------------------------------------- */
      /* SAVE ANSWER                                                         */
      /* ------------------------------------------------------------------- */

      addHistoryAnswer(
        historyAnswer
      );

      /* ------------------------------------------------------------------- */
      /* UPDATE STRUCTURED VALUES                                            */
      /* ------------------------------------------------------------------- */

      updateStructuredValue(
        currentQuestion,
        structuredAnswer
      );

      /* ------------------------------------------------------------------- */
      /* CHIEF COMPLAINT                                                      */
      /* ------------------------------------------------------------------- */

      if (
        currentQuestion.id ===
        "CHIEF_COMPLAINT"
      ) {
        handleChiefComplaintAnswer(
          answer,
          selectedAnswers
        );

        return;
      }

      /* ------------------------------------------------------------------- */
      /* PRIORITY / RED-FLAG CHECK                                             */
      /* ------------------------------------------------------------------- */

      const priorityMessage =
        getPriorityAlert(
          currentQuestion,
          structuredAnswer
        );

      if (priorityMessage) {
        stopListening();
        stopSpeaking();
        setIsListening(false);
        setIsSpeaking(false);
        setPriorityAlert(
          priorityMessage
        );
        return;
      }

      /* ------------------------------------------------------------------- */
      /* OTHER CATEGORY                                                       */
      /* ------------------------------------------------------------------- */

      if (
        currentQuestion.id ===
        "OTHER_CATEGORY"
      ) {
        const category =
          selectedAnswer;

        /*
         * If the patient cannot map the complaint to
         * a predefined pathway, collect one free-text
         * description instead of asking generic questions.
         */
        if (
          category ===
          "something-else"
        ) {
          setQuestions([
            createOtherFreeTextQuestion(),
          ]);

          setQuestionIndex(0);
          clearCurrentInput();
          return;
        }

        const specific =
          otherSpecificOptions[
            category
          ] || [];

        if (!specific.length) {
          const mapped =
            mapOtherCategoryToComplaintKey(
              category
            );

          const combined =
            Array.from(
              new Set([
                ...pendingComplaintKeys,
                ...(mapped
                  ? [mapped]
                  : []),
              ])
            );

          setActiveComplaintKeys(
            combined
          );
          setPendingComplaintKeys(
            []
          );

          const flow =
            combined.length
              ? buildComplaintFlow(
                  combined,
                  [
                    ...historyAnswers,
                    historyAnswer,
                  ]
                )
              : buildSequentialQuestions(
                  otherFollowUpQuestions,
                  [
                    ...historyAnswers,
                    historyAnswer,
                  ]
                );

          if (!flow.length) {
            finishHistory();
            return;
          }

          setQuestions(
            flow
          );
          setQuestionIndex(0);
          clearCurrentInput();
          return;
        }

        /*
         * Category selected.
         * Show only the specific options for that category.
         */
        setQuestions([
          {
            id: "OTHER_SPECIFIC",
            section:
              "Chief Complaint",
            text:
              "Which of these best describes your problem?",
            options:
              specific,
            required: true,
          },
        ]);

        setQuestionIndex(0);
        clearCurrentInput();
        return;
      }

      /* ------------------------------------------------------------------- */
      /* OTHER SPECIFIC                                                       */
      /* ------------------------------------------------------------------- */

      if (
        currentQuestion.id ===
        "OTHER_SPECIFIC"
      ) {
        const mapped =
          mapOtherSpecificToComplaintKey(
            selectedAnswer
          );

        const combined =
          Array.from(
            new Set([
              ...pendingComplaintKeys,
              ...(mapped
                ? [mapped]
                : []),
            ])
          );

        /*
         * If a specific selection has a known complaint
         * pathway, continue with that adaptive pathway.
         */
        if (combined.length) {
          setActiveComplaintKeys(
            combined
          );
          setPendingComplaintKeys(
            []
          );

          const flow =
            buildComplaintFlow(
              combined,
              [
                ...historyAnswers,
                historyAnswer,
              ]
            );

          if (!flow.length) {
            finishHistory();
            return;
          }

          setQuestions(
            flow
          );
          setQuestionIndex(0);
          clearCurrentInput();
          return;
        }

        /*
         * Urinary, women's-health and other categories
         * currently do not have a dedicated pathway in
         * this file. Keep the history focused rather than
         * inventing unrelated Ayurveda questions.
         */
        setActiveComplaintKeys([]);
        setPendingComplaintKeys([]);

        const fallbackFlow =
          buildSequentialQuestions(
            otherFollowUpQuestions,
            [
              ...historyAnswers,
              historyAnswer,
            ]
          );

        if (!fallbackFlow.length) {
          finishHistory();
          return;
        }

        setQuestions(
          fallbackFlow
        );
        setQuestionIndex(0);
        clearCurrentInput();
        return;
      }

      /* ------------------------------------------------------------------- */
      /* OTHER FREE TEXT                                                      */
      /* ------------------------------------------------------------------- */

      if (
        currentQuestion.id ===
        "OTHER_FREE_TEXT"
      ) {
        const detected =
          detectComplaintKeys(
            answer
          );

        const fallbackComplaintKey =
          getComplaintKey(answer);

        const detectedWithFallback =
          detected.length > 0
            ? detected
            : fallbackComplaintKey !== "other"
              ? [fallbackComplaintKey]
              : [];

        const combined =
          Array.from(
            new Set([
              ...pendingComplaintKeys,
              ...detectedWithFallback,
            ])
          );

        if (combined.length) {
          setActiveComplaintKeys(
            combined
          );
          setPendingComplaintKeys(
            []
          );

          const flow =
            buildComplaintFlow(
              combined,
              [
                ...historyAnswers,
                historyAnswer,
              ]
            );

          if (!flow.length) {
            finishHistory();
            return;
          }

          setQuestions(
            flow
          );
          setQuestionIndex(0);
          clearCurrentInput();
          return;
        }

        setActiveComplaintKeys([]);
        setPendingComplaintKeys([]);

        const fallbackFlow =
          buildSequentialQuestions(
            otherFollowUpQuestions,
            [
              ...historyAnswers,
              historyAnswer,
            ]
          );

        if (!fallbackFlow.length) {
          finishHistory();
          return;
        }

        setQuestions(
          fallbackFlow
        );
        setQuestionIndex(0);
        clearCurrentInput();
        return;
      }

      /* ------------------------------------------------------------------- */
      /* NORMAL ADAPTIVE NEXT QUESTION                                        */
      /* ------------------------------------------------------------------- */

      const allAnswers = [
        ...historyAnswers,
        historyAnswer,
      ];

      /*
       * Rebuild the flow after every answer.
       *
       * This is the core adaptive behavior:
       * Answer → evaluate relevance → rebuild only the
       * questions that are now relevant → show the next one.
       */
      const rebuiltFlow =
        buildComplaintFlow(
          activeComplaintKeys,
          allAnswers
        );

      const nextIndex =
        findNextQuestionIndex(
          rebuiltFlow,
          0,
          allAnswers,
          ""
        );

      if (
        nextIndex === -1
      ) {
        finishHistory();
        return;
      }

      setQuestions(
        rebuiltFlow
      );

      setQuestionIndex(
        nextIndex
      );

      clearCurrentInput();
    };

  /* ======================================================================= */
  /* CHIEF COMPLAINT ANSWER                                                  */
  /* ======================================================================= */

  const handleChiefComplaintAnswer =
    (
      answer: string,
      selectedValues: string[]
    ) => {
      /*
       * Chief Complaint supports MULTIPLE selections.
       *
       * Example:
       * Headache + Stomach problem
       *
       * Both pathways are retained and the engine walks
       * through the first complaint completely before
       * moving to the next complaint.
       */
      const selectedKeys =
        selectedValues
          .map(
            normalizeComplaintId
          )
          .filter(Boolean);

      const hasOther =
        selectedValues.includes(
          "other"
        );

      /*
       * If predefined complaints were selected,
       * preserve all of them.
       */
      if (
        selectedKeys.length &&
        !hasOther
      ) {
        const uniqueKeys =
          Array.from(
            new Set(
              selectedKeys
            )
          );

        setChiefComplaint(
          answer
        );

        setActiveComplaintKeys(
          uniqueKeys
        );

        setPendingComplaintKeys(
          []
        );

        const flow =
          buildComplaintFlow(
            uniqueKeys,
            historyAnswers
          );

        if (!flow.length) {
          finishHistory();
          return;
        }

        setQuestions(
          flow
        );

        setQuestionIndex(0);
        clearCurrentInput();
        return;
      }

      /*
       * "Other" can be selected together with
       * predefined complaints. Keep those complaints
       * while we collect the "Other" category.
       */
      if (hasOther) {
        setChiefComplaint(
          answer
        );

        setPendingComplaintKeys(
          Array.from(
            new Set(
              selectedKeys
            )
          )
        );

        setQuestions([
          {
            id:
              "OTHER_CATEGORY",
            section:
              "Chief Complaint",
            text:
              "What type of problem are you experiencing?",
            options:
              otherCategoryOptions,
            required: true,
          },
        ]);

        setQuestionIndex(0);
        clearCurrentInput();
        return;
      }

      /*
       * Free-text chief complaint.
       *
       * The detector can return multiple complaint
       * pathways from one sentence.
       */
      setChiefComplaint(
        answer
      );

      const detected =
        detectComplaintKeys(
          answer
        );

      const complaintKeys =
        Array.from(
          new Set(
            detected
          )
        );

      if (
        complaintKeys.length
      ) {
        setActiveComplaintKeys(
          complaintKeys
        );

        setPendingComplaintKeys(
          []
        );

        const flow =
          buildComplaintFlow(
            complaintKeys,
            historyAnswers
          );

        if (!flow.length) {
          finishHistory();
          return;
        }

        setQuestions(
          flow
        );

        setQuestionIndex(0);
        clearCurrentInput();
        return;
      }

      /*
       * We could not safely classify the free-text
       * complaint. Ask the patient to choose a broad
       * category instead of dumping generic questions.
       */
      setPendingComplaintKeys([]);
      setQuestions([
        {
          id:
            "OTHER_CATEGORY",
          section:
            "Chief Complaint",
          text:
            "What type of problem are you experiencing?",
          options:
            otherCategoryOptions,
          required: true,
        },
      ]);

      setQuestionIndex(0);
      clearCurrentInput();
    };

  /* ======================================================================= */
  /* FINISH                                                                  */
  /* ======================================================================= */

  const finishHistory =
    () => {
      stopListening();
      stopSpeaking();

      setIsListening(false);
      setIsSpeaking(false);

      navigate(
        "/patient/documents"
      );
    };

  /* ======================================================================= */
  /* CLEAR INPUT                                                             */
  /* ======================================================================= */

  const clearCurrentInput =
    () => {
      setSelectedAnswer("");
      setSelectedAnswers([]);
      setFreeText("");
      setSpeechError("");

      autoSpokenQuestion.current =
        null;
    };

  /* ======================================================================= */
  /* NO QUESTION                                                             */
  /* ======================================================================= */

  if (!currentQuestion) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[#F7F3E9] text-[#174638]">
        <div className="text-center">
          <p className="font-serif text-3xl font-semibold">
            {translateHistoryUI(
              language,
              "preparing"
            )}
          </p>

          <p className="mt-3 text-sm text-[#74827B]">
            {translateHistoryUI(
              language,
              "pleaseWait"
            )}
          </p>
        </div>
      </div>
    );
  }

  if (priorityAlert) {
    return (
      <div className="min-h-screen bg-[#F7F3E9] px-6 py-10 text-[#173F35]">
        <main className="mx-auto flex min-h-[70vh] max-w-3xl items-center justify-center">
          <section className="w-full rounded-[28px] border border-[#E6C7BC] bg-[#FFF8F4] p-8 text-center shadow-sm md:p-12">
            <div className="mx-auto flex h-20 w-20 items-center justify-center rounded-full bg-[#C96846]">
              <span className="text-3xl font-bold text-white">
                !
              </span>
            </div>

            <p className="mt-7 text-xs font-bold uppercase tracking-[0.18em] text-[#A45237]">
              Priority attention
            </p>

            <h1 className="mt-4 font-serif text-3xl font-semibold leading-tight text-[#174638] md:text-4xl">
              Please see healthcare staff
            </h1>

            <p className="mx-auto mt-5 max-w-2xl text-base leading-7 text-[#687970]">
              {priorityAlert}
            </p>

            <button
              type="button"
              onClick={finishHistory}
              className="mt-8 inline-flex h-14 items-center justify-center rounded-2xl bg-[#12634C] px-8 font-semibold text-white transition hover:bg-[#0E513E]"
            >
              Continue to healthcare staff
            </button>
          </section>
        </main>
      </div>
    );
  }

  /* ======================================================================= */
  /* DISPLAY VALUES                                                          */
  /* ======================================================================= */

  const displayedQuestion =
    translateQuestionText(
      currentQuestion,
      language
    );

  /* ======================================================================= */
  /* RENDER                                                                  */
  /* ======================================================================= */

  return (
    <div className="min-h-screen bg-[#F7F3E9] text-[#173F35]">

      {/* =================================================================== */}
      {/* PROGRESS                                                             */}
      {/* =================================================================== */}

      <div className="border-b border-[#E5DED1] bg-[#FBF8F2] py-5">
        <div className="mx-auto flex max-w-5xl justify-center gap-2 px-6">
          {Array.from({
            length: 8,
          }).map(
            (_, index) => (
              <div
                key={index}
                className={`h-2 rounded-full transition-all ${
                  index <=
                  Math.min(
                    7,
                    Math.floor(
                      progress / 12.5
                    )
                  )
                    ? "w-9 bg-[#174D3B]"
                    : "w-9 bg-[#D9D0BE]"
                }`}
              />
            )
          )}
        </div>
      </div>

      {/* =================================================================== */}
      {/* MAIN                                                                 */}
      {/* =================================================================== */}

      <main className="mx-auto max-w-5xl px-6 py-10">

        {/* ================================================================= */}
        {/* HEADER                                                             */}
        {/* ================================================================= */}

        <div className="text-center">

          <p className="text-sm font-semibold uppercase tracking-[0.18em] text-[#C96846]">
            {translateHistoryUI(
              language,
              "adaptiveHistory"
            )}
          </p>

          <h1 className="mx-auto mt-5 max-w-4xl font-serif text-4xl font-semibold leading-tight text-[#174638] md:text-5xl">
            {displayedQuestion}
          </h1>

          <p className="mt-3 text-sm font-medium text-[#74827B]">
            {translateSection(
              currentQuestion.section,
              language
            )}
          </p>

          {currentQuestion.complaint && (
            <p className="mt-2 text-xs font-medium uppercase tracking-[0.12em] text-[#A18C72]">
              {getComplaintDisplayName(
                currentQuestion.complaint,
                language
              )}
            </p>
          )}
        </div>

        {/* ================================================================= */}
        {/* QUESTION CARD                                                      */}
        {/* ================================================================= */}

        <section className="mt-9 rounded-[28px] border border-[#E0D8CA] bg-[#FBF9F4] p-7 shadow-sm md:p-9">

          {/* =============================================================== */}
          {/* SPEAKER                                                          */}
          {/* =============================================================== */}

          {(isVoiceToVoice ||
            isTextToVoice) && (
            <button
              type="button"
              onClick={() => {
                setIsSpeaking(
                  true
                );

                speakText(
                  displayedQuestion,
                  getSpeechLanguage(
                    language
                  )
                );

                window.setTimeout(
                  () => {
                    setIsSpeaking(
                      false
                    );
                  },
                  3000
                );
              }}
              className="mx-auto flex flex-col items-center"
            >
              <div
                className={`flex h-24 w-24 items-center justify-center rounded-full bg-[#12634C] shadow-md transition ${
                  isSpeaking
                    ? "scale-105"
                    : ""
                }`}
              >
                <Volume2
                  size={34}
                  className="text-white"
                />
              </div>

              <p className="mt-4 text-base font-medium text-[#687970]">
                {isSpeaking
                  ? translateHistoryUI(
                      language,
                      "speakingQuestion"
                    )
                  : translateHistoryUI(
                      language,
                      "tapToHearQuestion"
                    )}
              </p>
            </button>
          )}

          {/* =============================================================== */}
          {/* OPTIONS                                                          */}
          {/* =============================================================== */}

          {showsOptions &&
            currentQuestion.options && (
            <>
              {currentQuestion.id ===
                "CHIEF_COMPLAINT" && (
                <p className="mb-4 text-center text-sm font-medium text-[#74827B]">
                  {translateHistoryUI(
                    language,
                    "selectAllThatApply"
                  )}
                </p>
              )}

              <div
                className={`grid gap-3 ${
                  currentQuestion.options.length >
                  6
                    ? "md:grid-cols-2"
                    : "md:grid-cols-2"
                }`}
              >
              {currentQuestion.options.map(
                (option) => {
                  const selected =
                    currentQuestion.id ===
                      "CHIEF_COMPLAINT"
                      ? selectedAnswers.includes(
                          option.value
                        )
                      : selectedAnswer ===
                        option.value;

                  return (
                    <button
                      key={
                        option.value
                      }
                      type="button"
                      onClick={() =>
                        handleOptionSelect(
                          option
                        )
                      }
                      className={`flex min-h-[68px] items-center justify-between rounded-2xl border px-5 py-4 text-left transition ${
                        selected
                          ? "border-[#174D3B] bg-[#E7F1EA] text-[#174D3B] shadow-sm"
                          : "border-[#DED5C6] bg-white text-[#315C4D] hover:border-[#7DA895] hover:bg-[#F5F8F3]"
                      }`}
                    >
                      <span className="text-base font-semibold">
                        {translateAnyOption(
                          option,
                          language
                        )}
                      </span>

                      {selected && (
                        <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-[#174D3B]">
                          <Check
                            size={16}
                            className="text-white"
                          />
                        </span>
                      )}
                    </button>
                  );
                }
              )}
              </div>
            </>
          )}

          {/* =============================================================== */}
          {/* VOICE INPUT                                                      */}
          {/* =============================================================== */}

          {allowsVoice && (
            <div
              className={`${
                showsOptions
                  ? "mt-7 border-t border-[#E5DED1] pt-7"
                  : ""
              }`}
            >
              <button
                type="button"
                onClick={
                  handleVoice
                }
                className="mx-auto flex flex-col items-center"
              >
                <div
                  className={`flex h-24 w-24 items-center justify-center rounded-full shadow-md transition ${
                    isListening
                      ? "scale-105 bg-[#C96846]"
                      : "bg-[#12634C]"
                  }`}
                >
                  {isListening ? (
                    <MicOff
                      size={34}
                      className="text-white"
                    />
                  ) : (
                    <Mic
                      size={34}
                      className="text-white"
                    />
                  )}
                </div>

                <p className="mt-4 text-base font-medium text-[#687970]">
                  {isListening
                    ? translateHistoryUI(
                        language,
                        "listening"
                      )
                    : showsOptions
                    ? translateHistoryUI(
                        language,
                        "orAnswerByVoice"
                      )
                    : translateHistoryUI(
                        language,
                        "tapToAnswerByVoice"
                      )}
                </p>
              </button>

              {freeText && (
                <div className="mt-6 rounded-2xl border border-[#DCCFBF] bg-white p-5">
                  <p className="text-xs font-bold uppercase tracking-[0.12em] text-[#C96846]">
                    {translateHistoryUI(
                      language,
                      "yourAnswer"
                    )}
                  </p>

                  <p className="mt-2 text-lg font-medium leading-7 text-[#315C4D]">
                    {freeText}
                  </p>
                </div>
              )}
            </div>
          )}

          {/* =============================================================== */}
          {/* MANUAL TEXT — ONLY 2 QUESTIONS                                  */}
          {/* =============================================================== */}

          {allowsManualTyping &&
            !isVoiceToVoice &&
            !isVoiceToText && (
            <div className="mt-6">

              <label className="text-sm font-semibold text-[#315C4D]">
                {translateHistoryUI(
                  language,
                  "describeOwnWords"
                )}
              </label>

              <textarea
                value={
                  freeText
                }
                onChange={(
                  event
                ) => {
                  setFreeText(
                    event.target
                      .value
                  );

                  /*
                   * For free text,
                   * selectedAnswer is
                   * also the answer.
                   */
                  setSelectedAnswer(
                    event.target
                      .value
                  );

                  setSelectedAnswers(
                    []
                  );

                  setSpeechError(
                    ""
                  );
                }}
                placeholder={translateHistoryUI(
                  language,
                  "describeProblem"
                )}
                rows={4}
                className="mt-2 w-full resize-none rounded-2xl border border-[#DED5C6] bg-white px-5 py-4 text-base text-[#315C4D] outline-none transition placeholder:text-[#9AA49F] focus:border-[#5E947F] focus:ring-2 focus:ring-[#DDEBE3]"
              />

            </div>
          )}

          {/* =============================================================== */}
          {/* ERROR                                                            */}
          {/* =============================================================== */}

          {speechError && (
            <div className="mt-5 rounded-xl border border-[#E6C7BC] bg-[#FFF4EF] px-4 py-3 text-sm text-[#A45237]">
              {speechError}
            </div>
          )}

          {/* =============================================================== */}
          {/* CONTINUE                                                         */}
          {/* =============================================================== */}

          <button
            type="button"
            onClick={
              handleContinue
            }
            disabled={
              !getAnswerValue()
            }
            className={`mt-7 flex h-[60px] w-full items-center justify-center gap-3 rounded-2xl font-semibold text-white shadow-sm transition ${
              getAnswerValue()
                ? "bg-[#12634C] hover:bg-[#0E513E]"
                : "cursor-not-allowed bg-[#A9B9B1]"
            }`}
          >
            {translateHistoryUI(
              language,
              "continue"
            )}

            <ArrowRight
              size={21}
            />
          </button>

        </section>

        {/* ================================================================= */}
        {/* MODE                                                               */}
        {/* ================================================================= */}

        <div className="mt-6 text-center">
          <p className="text-sm text-[#74827B]">
            {getModeDescription(
              mode,
              language
            )}
          </p>
        </div>

        {/* ================================================================= */}
        {/* PROGRESS TEXT                                                      */}
        {/* ================================================================= */}

        <div className="mt-5 text-center text-xs font-medium text-[#87938D]">

          {translateHistoryUI(
            language,
            "question"
          )}{" "}

          {questionIndex + 1}{" "}

          {translateHistoryUI(
            language,
            "of"
          )}{" "}

          {questions.length}

          <span className="mx-2">
            •
          </span>

          {progress}%{" "}

          {translateHistoryUI(
            language,
            "complete"
          )}

        </div>

        {/* ================================================================= */}
        {/* BACK                                                               */}
        {/* ================================================================= */}

        <div className="mt-8 flex justify-center">

          <button
            type="button"
            onClick={() => {
              if (
                questionIndex >
                0
              ) {
                setQuestionIndex(
                  questionIndex - 1
                );

                clearCurrentInput();

                return;
              }

              navigate(
                "/patient/mode"
              );
            }}
            className="inline-flex items-center gap-2 rounded-xl border border-[#DED5C6] bg-white px-5 py-3 text-sm font-medium text-[#315C4D] transition hover:bg-[#FBF8F2]"
          >
            <ArrowLeft
              size={17}
            />

            {translateHistoryUI(
              language,
              "back"
            )}
          </button>

        </div>

      </main>
    </div>
  );
}